/// <summary>
/// HSMobileOpsCountControlSvc's request: the company, the supervisor (UserName) and their store
/// (WarehouseId); for decideBin the count (LineId) and KEEP, SUM or REJECT (Decision); for
/// getCountedTwice whether the decided bins are wanted (Decided); for holdStoreJournal Hold or
/// release (Hold).
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountCtlRequest
{
    str dataAreaId;
    str userName;
    str warehouseId;
    str lineId;
    str decision;
    boolean decided;
    boolean hold;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
}

[DataMemberAttribute('WarehouseId')]
public str parmWarehouseId(str _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}

[DataMemberAttribute('LineId')]
public str parmLineId(str _value = lineId)
{
    lineId = _value;
    return lineId;
}

[DataMemberAttribute('Decision')]
public str parmDecision(str _value = decision)
{
    decision = _value;
    return decision;
}

[DataMemberAttribute('Decided')]
public boolean parmDecided(boolean _value = decided)
{
    decided = _value;
    return decided;
}

[DataMemberAttribute('Hold')]
public boolean parmHold(boolean _value = hold)
{
    hold = _value;
    return hold;
}
